    faq1_q: "Как работает Landly?",
    faq1_a: "Просматривайте сотни предложений от компаний по всему Израилю и покупайте именно те, которые хотите, по цене, указанной в предложении — без подписки. После покупки покажите QR-код, чтобы воспользоваться им — без карты, без наличных, без лишних хлопот.",
