    terms_updated_date: "октябрь 2026",
    terms_h1: "1. Оплата",
    terms_p1: "Landly работает по модели оплаты за отдельные предложения: вы платите только за те предложения, которые решаете купить, по цене, указанной в этом предложении, без подписки и без периодических списаний какого-либо рода. Все цены указаны в израильских шекелях и включают НДС.",
