    terms_p2a_label: "В течение 14 дней:",
    terms_p2a: "Вы можете отменить покупку в течение 14 дней с даты покупки, если купон ещё не использован. Из суммы возврата может быть удержана плата за отмену — 5% от цены или ₪100, в зависимости от того, что меньше; деньги возвращаются на исходный способ оплаты.",
    terms_p2b_label: "После использования:",
