    terms_h3: "3. Купоны и предложения",
    terms_p3: "Каждый купон действует в течение срока, указанного в предложении и при оформлении заказа (180 дней с момента покупки, если не указано иное); дата окончания срока видна в вашем кошельке. Купон используется в заведении на условиях, указанных в предложении, привязан к вашему аккаунту Landly и не подлежит передаче.",
    terms_p3b_label: "Только для участников:",
    terms_p3b: "Просматривать привилегии на Landly может любой посетитель без аккаунта. Покупка привилегии, получение и использование кодов ваучеров, а также полные условия и порядок использования от партнёров доступны только зарегистрированным участникам, вошедшим в аккаунт.",
    terms_h4: "4. Закрытие аккаунта",
    terms_p4a_label: "Как закрыть:",
    terms_p4a: "Вы можете в любой момент попросить закрыть аккаунт Landly и удалить ваши персональные данные: в разделе Настройки → Удалить аккаунт на сайте или в приложении либо письмом на contact@golandly.com с адреса, привязанного к аккаунту.",
    terms_p4b_label: "В течение 30 дней:",
