    terms_link: "Términos y Condiciones",
    privacy_link: "Política de Privacidad",
    bottomCta_title: "¿Listo para empezar a ahorrar?",
    bottomCta_sub: "Únete al club hoy y sé el primero en saber cuándo lleguen nuevas ofertas y planes.",
    bottomCta_btn: "Regístrate Ahora",
    faq_label: "Preguntas Frecuentes",
    faq_label_short: "FAQ",
    faq_title: "Preguntas comunes.",
    faq1_q: "¿Cómo funciona Landly?",
    faq1_a: "Explora cientos de ofertas de negocios en todo Israel y compra solo las que quieras, al precio indicado en cada oferta — sin necesidad de suscripción. Después de comprar, muestra tu código QR para canjearla — sin tarjeta, sin efectivo, sin complicaciones.",
    faq4_q: "¿Cómo canjeo cupones en un negocio?",
    faq4_a: "Todas las compras y canjes se realizan a través de tu cuenta de Landly. Compra un cupón, ábrelo en el establecimiento y muestra el código QR al personal. El cupón se marca automáticamente como usado.",
    faq5_q: "¿Puedo obtener un reembolso por una compra?",
    faq5_a: "Puedes solicitar un reembolso completo en cualquier momento antes de que tu vale para esa oferta haya sido canjeado en el negocio. Una vez que un vale ha sido canjeado, esa compra es definitiva y no reembolsable.",
    faq_see_full: "Consulta nuestros",
    faq6_q: "¿Cómo contacto al servicio de atención al cliente?",
    faq6_a_pre: "Puedes contactarnos a través de la",
    faq6_link: "página de Atención al Cliente",
    faq6_a_post: ", por correo a contact@golandly.com. Ofrecemos soporte en inglés, ruso, español y francés, y buscamos responder en 24 horas.",
    home_faq_prompt_pre: "¿Tienes alguna pregunta?",
    home_faq_prompt_link: "Visita Soporte",
    footer_tagline: "Vive Israel como un local. Descuentos, derechos y comunidad en un solo lugar.",
    footer_location: "Tel Aviv, Israel",
    footer_biz_login: "¿Tienes un negocio? Inicia sesión aquí",
    terms_title: "Términos y Condiciones",
    terms_updated_label: "Última actualización:",
    terms_updated_date: "Octubre de 2026",
    terms_h1: "1. Pagos",
    terms_p1: "Landly funciona con pago por oferta: solo pagas por las ofertas individuales que decides comprar, al precio indicado en cada una, sin suscripciones ni cobros recurrentes de ningún tipo. Todos los precios están en séqueles israelíes e incluyen IVA.",
    terms_h2: "2. Cancelación y Reembolsos",
    terms_p2a_label: "En un plazo de 14 días:",
    terms_p2a: "Puedes cancelar una compra en los 14 días siguientes a la fecha de compra, siempre que el cupón no se haya canjeado. Del reembolso puede descontarse un cargo por cancelación del 5 % del precio o ₪100, lo que sea menor; el reembolso se hace al método de pago original.",
    terms_p2b_label: "Después del canje:",
    terms_p2b: "Una vez canjeado el cupón en el negocio, la compra es definitiva y no reembolsable.",
    terms_h3: "3. Cupones y Ofertas",
    terms_p3: "Cada cupón es válido durante el plazo indicado en su oferta y en el pago (180 días desde la compra, salvo que se indique otra cosa); su fecha de caducidad aparece en tu cartera. Los cupones se canjean en el negocio según las condiciones de canje de la oferta, están vinculados a tu cuenta de Landly y no son transferibles.",
    terms_p3b_label: "Solo para miembros:",
    terms_p3b: "Cualquier persona puede explorar los beneficios que muestra Landly sin una cuenta. Comprar un beneficio, recibir y canjear códigos de cupón, y ver los detalles y condiciones completos de canje del socio están disponibles solo para miembros registrados que hayan iniciado sesión.",
    terms_h4: "4. Cierre de la Cuenta",
    terms_p4a_label: "Cómo cerrarla:",
    terms_p4a: "Puedes pedirnos en cualquier momento que cerremos tu cuenta de Landly y eliminemos tus datos personales, en Ajustes → Eliminar cuenta en el sitio web o en la app, o escribiendo a contact@golandly.com desde la dirección registrada en tu cuenta.",
    terms_p4b_label: "En 30 días:",
    terms_p4b: "Eliminamos tu cuenta y tus datos personales, y te lo confirmamos por correo, en un plazo de 30 días desde tu solicitud. Los registros de pedidos y transacciones que la ley nos obliga a conservar se mantienen, sin vínculo con una cuenta activa, según se describe en nuestra Política de Privacidad.",
    terms_p4c_label: "Cupones sin canjear:",
    terms_p4c: "Al cerrar tu cuenta se cancelan los cupones que no hayas canjeado y no se pueden recuperar. Si una compra sigue dentro de su plazo de cancelación de 14 días, cancélala como se indica en la sección 2 antes de pedir el cierre de tu cuenta y te reembolsaremos al método de pago original.",
    terms_p4_link: "Ir a Eliminar cuenta",
    terms_h6: "5. Ley Aplicable",
    terms_p6: "Estos términos se rigen por las leyes del Estado de Israel. Cualquier disputa se resolverá en los tribunales de Tel Aviv-Yafo.",
    terms_h7: "6. Vendedor y Contacto",
    terms_p7: "Landly opera desde Tel Aviv-Yafo, Israel. Si tienes preguntas sobre estos términos, un pedido o una cancelación, escríbenos a contact@golandly.com.",
