    olim_title: "¿Nuevo en Israel? Landly Está Aquí para Ti.",
    olim_sub: "Ya sea que hagas Aliá, sirvas como soldado solitario, estudies o simplemente te estés instalando, Landly es tu compañero para la vida en Israel: beneficios para tus finanzas y tu día a día, y apoyo en tu propio idioma desde el primer día.",
