    biz_form_submit: "Enviar consulta",
    biz_page_title: "Crece con Landly",
    biz_page_intro: "Landly conecta a clientes internacionales de calidad — expatriados, participantes de Masa, nuevos Olim y turistas — con negocios locales israelíes confiables que ofrecen precios justos y transparentes. Unirte a Landly significa asociarte con una comunidad creciente de clientes comprometidos y leales que gastan activamente y exploran Israel.",
