    biz_page_intro: "Landly met en relation des clients internationaux de qualité — expatriés, stagiaires Massa, nouveaux Olim et touristes — avec des commerces israéliens locaux fiables qui pratiquent des prix justes et transparents. Rejoindre Landly, c'est s'associer à une communauté grandissante de clients engagés et fidèles qui dépensent activement et explorent Israël.",
