    faq1_q: "איך Landly עובד?",
    faq1_a: "עיינו במאות מבצעים מעסקים ברחבי ישראל ורכשו רק את אלה שמעניינים אתכם, במחיר המצוין בכל מבצע — בלי צורך במנוי. לאחר הרכישה, הציגו את קוד ה-QR כדי לממש אותו — בלי כרטיס, בלי מזומן, בלי כאב ראש.",
    faq4_q: "איך ממשים קופון בבית עסק?",
    faq4_a: "כל הרכישות והמימושים מתבצעים דרך חשבון Landly שלכם. רוכשים קופון, פותחים אותו במקום ומציגים את קוד ה-QR לצוות. הקופון מסומן אוטומטית כמומש.",
